class Manager:
    def __init__(self):
        self.added = []
        self.cancelled = []

    def add_request(self, _inputs, *, request_id, max_new_tokens, streaming):
        self.added.append((request_id, max_new_tokens, streaming))
        return request_id

    def request_id_iter(self, request_id):
        if request_id == "req-disconnect":
            raise asyncio.CancelledError()
        yield SimpleNamespace(status=RequestStatus.FINISHED, generated_tokens=[])

    def cancel_request(self, request_id):
        self.cancelled.append(request_id)


def test_stream_disconnect_and_next_request():
    manager = Manager()
    server = Serve.__new__(Serve)
    server.last_model = "fixture-model"
    server.running_continuous_batching_manager = manager
    server.process_model_name = lambda _model: "fixture-model"
    server.load_model_and_processor = lambda _model: (
        SimpleNamespace(generation_config=GenerationConfig(max_new_tokens=4), device="cpu"),
        Processor(),
    )
    server.build_chat_completion_chunk = lambda request_id="", **kwargs: {
        "id": request_id,
        "finish_reason": kwargs.get("finish_reason"),
    }
    server.chunk_to_sse_element = lambda chunk: f"data: {chunk['id']}:{chunk['finish_reason']}\n\n"

    async def exercise():
        request = {"model": "fixture-model", "messages": [{"role": "user", "content": "one"}], "stream": True}
        response = server.continuous_batching_chat_completion(request, "req-disconnect")
        iterator = response.body_iterator
        first = await anext(iterator)
        assert "req-disconnect" in first
        try:
            await anext(iterator)
        except StopAsyncIteration:
            pass
        else:
            raise AssertionError("disconnected stream yielded another item")

        response = server.continuous_batching_chat_completion(request, "req-next")
        following = [item async for item in response.body_iterator]
        return following

    following = asyncio.run(exercise())
    assert manager.cancelled == ["req-disconnect"]
    assert [item[0] for item in manager.added] == ["req-disconnect", "req-next"]
    assert len(following) == 2
    print("cancelled_request_ids", manager.cancelled)
    print("accepted_request_ids", [item[0] for item in manager.added])
